function handle(input, context) {
  const alertId = input.alertId;

  if (!alertId) {
    throw new Error("alertId is required");
  }

  const alert = context.alert.get(alertId);

  if (!alert) {
    throw new Error("Alert not found: " + alertId);
  }

  const observables = context.query.execute([
    {
      _name: "getAlert",
      idOrName: alertId
    },
    {
      _name: "observables"
    }
  ]);

  return {
    alert: alert,
    observables: observables
  };
}
